// A policy-wide modifier: a rate assessed on the policy base premium, either
// in MHPCO's favour (a surcharge) or the customer's (a discount).
interface PolicyWideModifier {
  appliesTo: (standing: CustomerStanding) => boolean;
  rate: number;
  isDiscount: boolean;
}

// Every item in a quote is treated as a first insurance, regardless of the
// customer's history, so this surcharge does not depend on the customer.
const alwaysApplies = (): boolean => true;

const isLongStanding = ({ customer }: CustomerStanding): boolean =>
  customer.yearsWithMHPCO >= LOYALTY_YEARS;

// Every contract after the customer's first is a follow-up contract.
const isFollowUpContract = ({ previousContracts }: CustomerStanding): boolean =>
  previousContracts > 0;

// The MHPCO's catalogue of policy-wide modifiers: which ones exist, when each
// applies, and at what rate. Changing the catalogue is independent of how the
// modifiers are assessed below.
const POLICY_WIDE_MODIFIERS: PolicyWideModifier[] = [
  {
    appliesTo: alwaysApplies,
    rate: FIRST_INSURANCE_SURCHARGE_RATE,
    isDiscount: false,
  },
  { appliesTo: isLongStanding, rate: LOYALTY_DISCOUNT_RATE, isDiscount: true },
  {
    appliesTo: isFollowUpContract,
    rate: FOLLOW_UP_CONTRACT_DISCOUNT_RATE,
    isDiscount: true,
  },
];

// Each modifier is assessed on the policy base premium separately rather than
// as a summed rate, so that intermediate amounts match the per-modifier figures
// in the MHPCO's own worked examples.
function assessedAmount(
  modifier: PolicyWideModifier,
  standing: CustomerStanding,
  basePremium: number,
): number {
  if (!modifier.appliesTo(standing)) return 0;
  const amount = basePremium * modifier.rate;
  return modifier.isDiscount ? -amount : amount;
}

// Policy-wide modifiers all apply to the policy base premium. Returns the net
// adjustment: surcharges positive, discounts negative.
function policyWideModifiers(
  standing: CustomerStanding,
  basePremium: number,
): number {
  return sum(
    POLICY_WIDE_MODIFIERS.map((modifier) =>
      assessedAmount(modifier, standing, basePremium),
    ),
  );
}

