24	const BLOCK_BASE_PREMIUM = 60;
25	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
26	const LOYALTY_YEARS = 2;
27	const LOYALTY_DISCOUNT_RATE = 0.2;
28	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
29	const CURSE_SURCHARGE_RATE = 0.5;
30	const HIGH_ENCHANTMENT_LEVEL = 5;
31	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
32	
33	function isComponent(item: Item): boolean {
34	  return COMPONENT_TYPES.has(item.type);
35	}
36	
37	function mainItemBasePremium(item: Item): number {
38	  return MAIN_ITEM_BASE_PREMIUMS[item.type];
39	}
40	
41	function sum(amounts: number[]): number {
42	  return amounts.reduce((total, amount) => total + amount, 0);
43	}
44	
45	function alikeComponentsBasePremium(alikeComponents: Item[]): number {
46	  return alikeComponents.length === BLOCK_SIZE
47	    ? BLOCK_BASE_PREMIUM
48	    : alikeComponents.length * COMPONENT_BASE_PREMIUM;
49	}
50	
51	// "Alike" components are components of exactly the same type, not merely of
52	// the same family; only alike components can form a building block.
53	function alikeKey(component: Item): string {
54	  return component.type;
55	}
56	
57	function groupAlikeComponents(components: Item[]): Item[][] {
58	  const groups = new Map<string, Item[]>();
59	  for (const component of components) {
60	    const key = alikeKey(component);
61	    const group = groups.get(key) ?? [];
62	    group.push(component);
63	    groups.set(key, group);
64	  }
65	  return [...groups.values()];
66	}
67	
68	function componentsBasePremium(components: Item[]): number {
69	  return sum(groupAlikeComponents(components).map(alikeComponentsBasePremium));
70	}
71	
72	export function policyBasePremium(items: Item[]): number {
73	  const components = items.filter(isComponent);
74	  const mainItems = items.filter((item) => !isComponent(item));
75	  return (
76	    sum(mainItems.map(mainItemBasePremium)) + componentsBasePremium(components)
77	  );
78	}
79	
80	// The basis an item-specific surcharge is assessed on. This is the item's own
81	// list price, deliberately not its share of the policy base premium: the block
82	// discount is a policy pricing rule, so a rune in a block is still assessed on
83	// the full 25 G.
84	function riskAssessmentBasis(item: Item): number {
85	  return isComponent(item) ? COMPONENT_BASE_PREMIUM : mainItemBasePremium(item);
86	}
87	
88	function isCursed(item: Item): boolean {
89	  return item.cursed === true;
90	}
91	
92	function isHighlyEnchanted(item: Item): boolean {
93	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
94	}
95	
96	// An item bears every risk factor it qualifies for; a cursed, highly enchanted
97	// item therefore carries both surcharges.
98	function itemRiskSurchargeRate(item: Item): number {
99	  const curse = isCursed(item) ? CURSE_SURCHARGE_RATE : 0;
100	  const highEnchantment = isHighlyEnchanted(item)
101	    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
102	    : 0;
103	  return curse + highEnchantment;
104	}
105	
106	function itemRiskSurcharge(item: Item): number {
107	  return riskAssessmentBasis(item) * itemRiskSurchargeRate(item);
108	}
109	
110	// Item-specific modifiers apply to the base premium of the affected item.
111	function itemRiskSurcharges(items: Item[]): number {
112	  return sum(items.map(itemRiskSurcharge));
113	}
114	
115	// The customer's standing with MHPCO, as far as the premium is concerned.
116	interface CustomerStanding {
117	  customer: Customer;
118	  previousContracts: number;
119	}
120	
121	// Every item in a quote is treated as a first insurance, regardless of the
122	// customer's history, so this surcharge does not depend on the customer.
123	function firstInsuranceSurcharge(basePremium: number): number {
124	  return basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
125	}
126	
127	function isLongStanding({ customer }: CustomerStanding): boolean {
128	  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
129	}
130	
131	function loyaltyDiscount(
132	  standing: CustomerStanding,
133	  basePremium: number,
134	): number {
135	  return isLongStanding(standing) ? basePremium * LOYALTY_DISCOUNT_RATE : 0;
136	}
137	
138	// Every contract after the customer's first is a follow-up contract.
139	function isFollowUpContract({ previousContracts }: CustomerStanding): boolean {
140	  return previousContracts > 0;
141	}
142	
143	function followUpContractDiscount(
144	  standing: CustomerStanding,
145	  basePremium: number,
146	): number {
147	  return isFollowUpContract(standing)
148	    ? basePremium * FOLLOW_UP_CONTRACT_DISCOUNT_RATE
149	    : 0;
150	}
151	
152	// Policy-wide modifiers (first insurance, loyalty, follow-up contract) all
153	// apply to the policy base premium. Returns the net adjustment: surcharges
154	// positive, discounts negative. Each modifier is applied to the base premium
155	// separately rather than as a summed rate, so that intermediate amounts match
156	// the per-modifier figures in the MHPCO's own worked examples.
157	function policyWideModifiers(
158	  standing: CustomerStanding,
159	  basePremium: number,
160	): number {
161	  return (
162	    firstInsuranceSurcharge(basePremium) -
163	    loyaltyDiscount(standing, basePremium) -
164	    followUpContractDiscount(standing, basePremium)
165	  );
166	}
167	
168	// All amounts are rounded to whole G in the MHPCO's favour. For a premium --
169	// money flowing to MHPCO -- its favour is upwards. (A payout, money flowing
170	// away from MHPCO, rounds the other way; that rule is not yet needed here.)
171	// Intermediate amounts are kept as fractions; only the final premium is
172	// rounded.
173	function roundPremiumInMhpcoFavor(premium: number): number {
174	  return Math.ceil(premium);
175	}
176	
177	export function quote(
178	  customer: Customer,
179	  items: Item[],
180	  previousContracts = 0,
181	): number {
182	  const basePremium = policyBasePremium(items);
183	  const premium =
184	    basePremium +
185	    itemRiskSurcharges(items) +
186	    policyWideModifiers({ customer, previousContracts }, basePremium) +
187	    PROCESSING_FEE;
188	  return roundPremiumInMhpcoFavor(premium);
189	}

